import { DocumentsOfTypeResult, SelectorResult, StudioProApi } from "@mendix/extensions-api";
import { Agent, Variable } from "../../types/agent";
import { calculateVariables, isAgentEntityFound } from "../../utils/agentUtils";
import { modelDocumentTypeId } from "../../main";


export const handleAgentChangeEvent = (studioPro: StudioProApi, field: keyof Agent, agent: Agent, documentId: string) => async (
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>
): Promise<Agent> => {
    console.log("agent change triggered for field ", field)
    if (field === "userPrompt" || field === "systemPrompt") {
        const updatedAgent = { ...agent, [field]: e.target.value };
        const newVariables: Variable[] = await calculateVariables(studioPro, updatedAgent);
        const updatedAgentWithVariables = { ...updatedAgent, variables: newVariables }
        await updateAgentDocument(studioPro, updatedAgentWithVariables, documentId);
        return updatedAgentWithVariables;
    }
    else {
        const updatedAgent = { ...agent, [field]: e.target.value }
        await updateAgentDocument(studioPro, updatedAgent, documentId);
        return updatedAgent;
    }
};


export const handleAgentChangeValue = (studioPro: StudioProApi, field: keyof Agent, agent: Agent, documentId: string) => async (
    value: string
): Promise<Agent> => {
    console.log("agent change triggered for field ", field)
    if (field === "userPrompt" || field === "systemPrompt" || field === "entity") {
        const updatedAgent = { ...agent, [field]: value };
        const newVariables: Variable[] = await calculateVariables(studioPro, updatedAgent);
        const updatedAgentWithVariables = { ...updatedAgent, variables: newVariables };
        await updateAgentDocument(studioPro, updatedAgentWithVariables, documentId);
        return updatedAgentWithVariables;
    }
    else {
        const updatedAgent = { ...agent, [field]: value }
        await updateAgentDocument(studioPro, updatedAgent, documentId);
        return updatedAgent;
    }
};


export const handleSelectEntity = async (studioPro: StudioProApi, agent: Agent, documentId: string): Promise<Agent | undefined> => {
    const selectorResult: SelectorResult = await studioPro.ui.elementSelectors.selectEntity({ allowNone: true });
    if (selectorResult.status === 'ok') {
        console.log(selectorResult);
        const updatedAgent: Agent = { ...agent, entity: selectorResult.selected.module + '.' + selectorResult.selected.name };
        await updateAgentDocument(studioPro, updatedAgent, documentId);
        return updatedAgent;
    }
    if (selectorResult.status === 'none') {
        console.log('"None" selected for Entity');
        const updatedAgent: Agent = { ...agent, entity: "" };
        await updateAgentDocument(studioPro, updatedAgent, documentId);
        return updatedAgent;
    }
}

export const handleSelectCustomDocument = async (studioPro: StudioProApi, agent: Agent, documentId: string, fieldName: keyof Agent): Promise<Agent | undefined> => {
    const selectorResult: SelectorResult = await studioPro.ui.elementSelectors.selectDocument({ allowNone: true });
    if (selectorResult.status === 'ok') {
        console.log(selectorResult);
        const updatedAgent: Agent = { ...agent, [fieldName]: selectorResult.selected.module + '.' + selectorResult.selected.name };
        console.log(selectorResult.selected.module + '.' + selectorResult.selected.name);
        await updateAgentDocument(studioPro, updatedAgent, documentId);
        return updatedAgent;
    }
    if (selectorResult.status === 'none') {
        console.log('"None" selected for ' + fieldName);
        const updatedAgent: Agent = { ...agent, [fieldName]: undefined };
        await updateAgentDocument(studioPro, updatedAgent, documentId);
        return updatedAgent;
    }
}

export const handleVariableTestValueChange = (studioPro: StudioProApi, agent: Agent, documentId: string) => async (
    index: number,
    value: string
): Promise<Agent> => {
    console.log("variable test value change triggered for index", index);
    const updatedVariables = [...agent.variables];
    updatedVariables[index] = { ...updatedVariables[index], testValue: value };
    const updatedAgent = { ...agent, variables: updatedVariables };
    await updateAgentDocument(studioPro, updatedAgent, documentId);
    return updatedAgent;
};

export const handleValidateAgent = async (field: keyof Agent, studioPro: StudioProApi, agent: Agent): Promise<true | string> => {
    console.log("HandleValidate triggered with field", field);
    switch (field) {
        case "modelQualifiedName":
            if (!agent.modelQualifiedName) {
                console.log("no model name found");
                return "Please select a model.";
            }
            const modelDocuments: DocumentsOfTypeResult = await studioPro.app.model.customBlobDocuments.getDocumentsOfType(modelDocumentTypeId);
            const matchOfCorrectType = modelDocuments.find(d => d.moduleName + '.' + d.name === agent.modelQualifiedName);
            if (!matchOfCorrectType) {
                console.log("Invalid document type selected for Model")
                return "This document is invalid. Make sure to select a document of type Model."
            }
            break;

        case "entity":
            if (agent.variables.length > 0 && !agent.entity) {
                return "Please select an entity.";
            }
            const [moduleName, entityDocument] = agent.entity.split('.');
            if (!moduleName || !entityDocument){
                return "The selected entity is not valid."
            }
            const isEntityFound = await isAgentEntityFound(studioPro, agent);
            if (!isEntityFound){
                return "Entity no longer exists."
            }
            break;

        case "userPrompt":
            if (!agent.userPrompt) {
                console.log("no user prompt found");
                return "Please provide a user prompt.";
            }
            break;

        default:
            return true;
    }
    return true;
}


const updateAgentDocument = async (studioPro: StudioProApi, agent: Agent, documentId: string) => {
    console.log("Save logic triggered");
    try {
        await studioPro.app.model.customBlobDocuments.updateDocumentContent(documentId, agent);
    } catch (error) {
        studioPro.ui.notifications.show({
            title: "Failed to save document",
            message: (error as Error).message
        });
    }
};